export function MarketMoodAnimal({ mood, label }: { mood: MarketMood; label: string }) {
  return (
    <figure className="mood-figure" aria-label={label}>
      {mood === "bull" ? <BullArt /> : <BearArt />}
      <figcaption className="num text-[11px] uppercase tracking-[0.3em] text-muted mt-2 text-center">
        {label}
      </figcaption>
    </figure>
  );
}
